from heapq import heappop, heappush


def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    events = []
    paint_count = 0

    for i, op in enumerate(ops):
        if op[0] == 1:
            _, l, r, colour = op
            events.append((l, i, colour))
            events.append((r + 1, i, 0))
            paint_count += 1
        else:
            _, l, r = op
            # Negative indices identify erase events and prioritize later ones.
            events.append((l, -i - 1, r))
            events.append((r + 1, -i - 1, 0))

    if paint_count == 0:
        return []

    events.sort()

    m = len(ops)
    size = 1 << (m - 1).bit_length()
    tree = [0] * (2 * size)
    erases = []
    counts = {}

    k = 0
    total_events = len(events)

    while k < total_events:
        x = events[k][0]

        while k < total_events and events[k][0] == x:
            _, index, value = events[k]

            if index < 0:
                if value:
                    heappush(erases, (index, value))
            else:
                # Each paint has its own leaf, ordered by operation time.
                node = size + index
                tree[node] = value
                node >>= 1

                while node:
                    left = tree[node << 1]
                    right = tree[node << 1 | 1]
                    maximum = left if left >= right else right
                    if tree[node] == maximum:
                        break
                    tree[node] = maximum
                    node >>= 1

            k += 1

        if k == total_events:
            break

        while erases and erases[0][1] < x:
            heappop(erases)

        colour = tree[1]

        if colour and erases:
            # Only paints after the latest active erase can contribute.
            first = -erases[0][0]

            if first >= m:
                colour = 0
            else:
                node = size + first
                best = tree[node]

                # Query the suffix [first, size).
                while node > 1 and best < colour:
                    if node & 1 == 0:
                        candidate = tree[node + 1]
                        if candidate > best:
                            best = candidate
                    node >>= 1

                colour = best

        if colour:
            width = events[k][0] - x
            counts[colour] = counts.get(colour, 0) + width

    return [[colour, count] for colour, count in sorted(counts.items())]
